<script setup lang="ts">
import {ref,watch,nextTick,onMounted} from 'vue';import {canvasPoint,type Pattern} from './engine';
const props=defineProps<{pattern:Pattern,chosen:string|null}>();const emit=defineEmits<{stroke:[cells:(string|null)[]],pick:[code:string|null]}>();
const canvas=ref<HTMLCanvasElement>(),stage=ref<HTMLDivElement>(),zoom=ref(1),tool=ref('brush'),highlight=ref('');let working:(string|null)[]|undefined,last:{x:number,y:number}|undefined,pan:number[]|undefined;
function draw(){const c=canvas.value;if(!c)return;const p=props.pattern;c.width=p.width*14;c.height=p.height*14;const x=c.getContext('2d')!,cells=working??p.cells,map=new Map(p.palette.map(v=>[v.code,v.hex]));for(let i=0;i<cells.length;i++){x.globalAlpha=highlight.value&&cells[i]!==highlight.value?.25:1;x.fillStyle=map.get(cells[i]??'')??'#edf0ea';x.fillRect(i%p.width*14,Math.floor(i/p.width)*14,14,14);x.strokeStyle='#0002';x.strokeRect(i%p.width*14,Math.floor(i/p.width)*14,14,14)}x.globalAlpha=1}
function pos(e:PointerEvent){const p=canvasPoint(e.clientX,e.clientY,canvas.value!.getBoundingClientRect(),props.pattern.width,props.pattern.height);return{x:Math.floor(p.x),y:Math.floor(p.y)}}
function paint(e:PointerEvent){const p=pos(e),a=last??p,n=Math.max(Math.abs(p.x-a.x),Math.abs(p.y-a.y),1);for(let i=0;i<=n;i++){const x=Math.round(a.x+(p.x-a.x)*i/n),y=Math.round(a.y+(p.y-a.y)*i/n);working![y*props.pattern.width+x]=props.chosen}last=p;draw()}
function down(e:PointerEvent){canvas.value!.setPointerCapture(e.pointerId);if(tool.value==='pan'){pan=[e.clientX,e.clientY,stage.value!.scrollLeft,stage.value!.scrollTop];return}if(tool.value==='pick'){const p=pos(e);emit('pick',props.pattern.cells[p.y*props.pattern.width+p.x]);tool.value='brush';return}working=props.pattern.cells.slice();paint(e)}
function move(e:PointerEvent){if(pan){stage.value!.scrollLeft=pan[2]+pan[0]-e.clientX;stage.value!.scrollTop=pan[3]+pan[1]-e.clientY}else if(working)paint(e)}
function up(){if(working&&working.some((v,i)=>v!==props.pattern.cells[i]))emit('stroke',working);working=undefined;last=undefined;pan=undefined;draw()}
watch(()=>props.pattern,()=>{working=undefined;last=undefined;void nextTick(draw)},{deep:true});watch(highlight,draw);onMounted(draw);
</script>
<template><div><div class="grid-tools"><button @click="zoom=Math.max(.25,zoom-.25)">−</button><span>{{Math.round(zoom*100)}}%</span><button @click="zoom=Math.min(4,zoom+.25)">＋</button><button v-for="[id,label] in [['brush','画笔'],['pan','移动'],['pick','吸色']]" :class="{active:tool===id}" @click="tool=id">{{label}}</button><select v-model="highlight" aria-label="高亮颜色"><option value="">全部颜色</option><option v-for="c in pattern.palette" :value="c.code">{{c.code}}</option></select></div><div class="grid-scroll" ref="stage"><canvas ref="canvas" :style="{width:pattern.width*14*zoom+'px',height:pattern.height*14*zoom+'px',touchAction:'none'}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up"/></div></div></template>
